from html.parser import HTMLParser
from pathlib import Path
class Check(HTMLParser):
    def __init__(self): super().__init__(); self.stack=[]; self.errors=[]
    void={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self,tag,attrs):
        if tag not in self.void:self.stack.append(tag)
    def handle_endtag(self,tag):
        if tag in self.void:return
        if tag not in self.stack:self.errors.append(f'unexpected </{tag}>');return
        while self.stack:
            top=self.stack.pop()
            if top==tag:break
            self.errors.append(f'missing </{top}> before </{tag}>')
p=Check();p.feed(Path('index.html').read_text());print('HTML structure:', 'ok' if not p.errors and not p.stack else p.errors or p.stack)
