  await page.goto('http://127.0.0.1:8765/',{waitUntil:'load'});
  await page.waitForTimeout(100);
  const layout=await page.evaluate(()=>({docWidth:document.documentElement.scrollWidth,innerWidth:innerWidth,scene:document.querySelector('#scene-wrap').getBoundingClientRect().toJSON(),pad:document.querySelector('#aim-pad').getBoundingClientRect().toJSON(),loose:document.querySelector('#loose-button').getBoundingClientRect().toJSON(),hint:document.querySelector('.shoot-tip').textContent}));
  await page.locator('#sound-button').click();
  const soundOn=await page.locator('#sound-button').getAttribute('aria-pressed');
  const p=await page.locator('#aim-pad').boundingBox();
  await page.mouse.move(p.x+p.width/2,p.y+p.height/2);
  await page.mouse.down();
  await page.mouse.move(p.x+p.width*.85,p.y+p.height*.48,{steps:4});
  await page.mouse.up();
  const knobBefore=await page.locator('#pad-knob').getAttribute('style');
  await page.locator('#loose-button').click();
  const immediate=await page.evaluate(()=>({knob:document.querySelector('#pad-knob').getAttribute('style'),disabled:document.querySelector('#loose-button').disabled,status:document.querySelector('#shoot-status').textContent}));
  await page.waitForTimeout(1050);
  const afterShot=await page.evaluate(()=>({shots:document.querySelector('#shot-count').textContent,coins:document.querySelector('#coin-count').textContent,disabled:document.querySelector('#loose-button').disabled,status:document.querySelector('#shoot-status').textContent}));
  await page.waitForTimeout(1000);
  const ready=await page.locator('#loose-button').isEnabled();
  console.log(JSON.stringify({viewport:viewport.name,layout,soundOn,knobBefore,immediate,afterShot,ready,errors}));
  await page.close();
 }
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
