const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1440,height:1000}});
  page.on('pageerror', e => console.error('PAGE ERROR', e.message));
  await page.addInitScript(() => { Math.random = () => 0.5; });
  await page.goto('http://127.0.0.1:8765', {waitUntil:'networkidle'});
  const wind = await page.locator('#wind-direction').innerText();
  const pad = page.locator('#aim-pad');
  const box = await pad.boundingBox();
  await page.mouse.move(box.x+box.width/2, box.y+box.height/2);
  await page.mouse.down();
  await page.mouse.move(box.x+box.width/2+45, box.y+box.height/2-35, {steps:3});
  await page.mouse.up();
  const persistedKnob = await page.locator('#pad-knob').evaluate(el=>el.style.transform);
  // Canceled center tap should not shoot.
  const shotsBefore = await page.locator('#shot-count').innerText();
  await page.evaluate(() => {
    const pad=document.querySelector('#aim-pad'), r=pad.getBoundingClientRect();
    const id=991;
    pad.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:id,clientX:r.left+r.width/2,clientY:r.top+r.height/2,pointerType:'touch'}));
    pad.dispatchEvent(new PointerEvent('pointercancel',{bubbles:true,cancelable:true,pointerId:id,clientX:r.left+r.width/2,clientY:r.top+r.height/2,pointerType:'touch'}));
  });
  await page.waitForTimeout(100);
  const shotsAfterCancel = await page.locator('#shot-count').innerText();
  // Fresh center tap fires and resets aim; keyboard Enter also activates the pad.
  await page.mouse.click(box.x+box.width/2, box.y+box.height/2);
  await page.waitForTimeout(250);
  const shotsAfterTap = await page.locator('#shot-count').innerText();
  const resetKnob = await page.locator('#pad-knob').evaluate(el=>el.style.transform);
  await page.setViewportSize({width:390,height:844});
  await page.waitForTimeout(100);
  const mobile = await page.evaluate(()=>({inner:innerWidth,scroll:document.documentElement.scrollWidth,shell:document.querySelector('.game-shell').getBoundingClientRect().width,pad:document.querySelector('#aim-pad').getBoundingClientRect().toJSON()}));
